import Header from '../components/Header';
import Footer from '../components/Footer';
function Partitions() {
    return (
        <div>
            <Header />
            <h1>Partitions</h1>
            
            <Footer />
        </div>
    )
}

function PdfViewer() {
    return (
        <iframe
            src="/documents/monfichier.pdf"
            width="100%"
            height="600px"
            title="PDF"
        />
    )
}

export default Partitions;
